import sys


def calc(expr: str) -> int | str:
    n = len(expr)
    i = 0
    old_limit = sys.getrecursionlimit()
    sys.setrecursionlimit(max(old_limit, 100000))

    class _Err(Exception):
        pass

    def skip() -> None:
        nonlocal i
        while i < n and expr[i] == " ":
            i += 1

    def trunc_div(a: int, b: int) -> int:
        if b == 0:
            raise _Err
        neg = (a < 0) ^ (b < 0)
        q = abs(a) // abs(b)
        return -q if neg else q

    def parse_sum() -> int:
        left = parse_product()
        while True:
            skip()
            if i >= n or expr[i] not in "+-":
                return left
            op = expr[i]
            i += 1
            right = parse_product()
            left = left + right if op == "+" else left - right

    def parse_product() -> int:
        left = parse_unary()
        while True:
            skip()
            if i >= n or expr[i] not in "*/%":
                return left
            op = expr[i]
            i += 1
            right = parse_unary()
            if op == "*":
                left = left * right
            else:
                q = trunc_div(left, right)
                left = q if op == "/" else left - right * q

    def parse_unary() -> int:
        skip()
        sign = 1
        while i < n and expr[i] == "-":
            i += 1
            sign = -sign
            skip()
        val = parse_power()
        return -val if sign < 0 else val

    def parse_power() -> int:
        base = parse_primary()
        skip()
        if i >= n or expr[i] != "^":
            return base
        i += 1
        exp = parse_unary()
        if exp < 0:
            raise _Err
        return pow(base, exp)

    def parse_primary() -> int:
        nonlocal i
        skip()
        if expr[i] == "(":
            i += 1
            val = parse_sum()
            skip()
            i += 1
            return val
        start = i
        while i < n and expr[i].isdigit():
            i += 1
        return int(expr[start:i])

    try:
        return parse_sum()
    except _Err:
        return "error"
    finally:
        sys.setrecursionlimit(old_limit)
